/// 把實數編碼成 API 的 u8：0–254 線性對應 [min, max]，255 保留給「不可通行／無資料」。
#[inline]
pub fn encode_u8(v: f32, min: f32, max: f32) -> u8 {
    if !v.is_finite() {
        return 255;
    }
    (((v - min) / (max - min)).clamp(0.0, 1.0) * 254.0).round() as u8
}

